ALTER TYPE "public"."document_references_relation" ADD VALUE 'external_application';--> statement-breakpoint
ALTER TABLE "document_references" DROP CONSTRAINT "document_references_relation_kind_chk";--> statement-breakpoint
ALTER TABLE "document_references" ADD CONSTRAINT "document_references_relation_kind_chk" CHECK (("document_references"."relation" = 'related_service' AND "document_references"."target_kind" = 'service') OR ("document_references"."relation" = 'application_form' AND "document_references"."target_kind" IN ('basic-form', 'multi-stage-form')) OR ("document_references"."relation"::text = 'service_agreement' AND "document_references"."target_kind" = 'service-agreement') OR ("document_references"."relation"::text = 'external_application' AND "document_references"."target_kind" = 'external-application'));